from pathlib import Path
from PIL import Image
import json,hashlib,subprocess,html,argparse
parser=argparse.ArgumentParser();parser.add_argument('work',type=Path);parser.add_argument('destination',type=Path);args=parser.parse_args();w=args.work;dest=args.destination;dest.mkdir(exist_ok=True)
vs=[('baseline','0 — текущая Г/v4','Контрольный вариант'),('gather-soft','1 — большой шаг, мягкий','Три крупных смешивающих переноса'),('gather-strong','2 — большой шаг, сильный','Тот же подход с большим расстоянием'),('jump4','3 — консервативный перенос','Дальние обмены + сохранение деталей кисти'),('jump8','4 — дальний консервативный','Более дальние обмены')]
cs=[('cross','Пересечение жёлтого и синего',(20,60,1000,960)),('single','Один мазок',(20,250,1010,780)),('puddle','Капля в чистой воде',(200,200,824,824)),('wide-cross','Два широких мазка, кисть 380',(0,0,1024,1024))]
stats={};sections=[];assets=[]
for c,title,crop in cs:
 cards=[]
 for v,name,desc in vs:
  row={};sources={}
  for device in ['samsung','amd']:
   src=(w/'samsung-wide' if c=='wide-cross' else w/'samsung') if device=='samsung' else w/'amd'
   source=src/f'{v}-{c}.png'
   if not source.exists():source=source.with_suffix('.jpg')
   report=json.loads((src/f'{v}-{c}.json').read_text());row[device]=report
   if report['gl'] or report['lost'] or report['errors']:raise Exception('GPU error')
   im=Image.open(source).convert('RGBA');paper=Image.new('RGBA',im.size,'white');im=Image.alpha_composite(paper,im).convert('RGB').crop(crop)
   fn=f'{device}-{v}-{c}.jpg';im.save(dest/fn,quality=94);sources[device]=fn;assets.append({'file':fn,'sha256':hashlib.sha256((dest/fn).read_bytes()).hexdigest()})
  stats[v+'-'+c]=row
  r=row['samsung'];time=f"{r['computeMs']/1000:.2f} с";rep=w/'samsung-repeat'/f'{v}-{c}.json'
  if rep.exists():
   rr=json.loads(rep.read_text());row['samsungRepeat']=rr;time=f"{r['computeMs']/1000:.2f} / {rr['computeMs']/1000:.2f} с"
  cards.append(f'''<article><h3>{name}</h3><p class="sub">{desc}</p><a class="full" href="{sources['samsung']}" target="_blank" rel="noopener"><img loading="lazy" src="{sources['samsung']}" data-samsung="{sources['samsung']}" data-amd="{sources['amd']}" alt="{html.escape(name+'; '+title)}"></a><p class="timing" data-key="{v+'-'+c}">{time}</p><button class="copy" data-name="{name}">Скопировать название</button></article>''')
  
 sections.append(f'<section id="{c}" '+('hidden' if c!='cross' else '')+f'><h2>{title}</h2><div class="grid">'+''.join(cards)+'</div></section>')
manifest={'baseline':'29545871','gather':subprocess.check_output(['git','-C','/home/suselman/projects/pencil-agents/728-dry-large-step','rev-parse','HEAD'],text=True).strip(),'jump':subprocess.check_output(['git','-C','/home/suselman/projects/pencil-agents/728-dry-multilevel','rev-parse','HEAD'],text=True).strip(),'stats':stats,'files':assets,'scope':'Independent static replay+Dry; 1024 squared fine paper, identical fixtures per device; ready after gl.finish; excludes paper load, mass readback and PNG export. Not input latency. Two cross runs, others single. Both prototype switches diagnostic only, main Mini remains v4.'}
(dest/'results.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
buttons=''.join(f'<button class="case" data-case="{c}" aria-pressed="'+('true' if c=='cross' else 'false')+f'">{title}</button>' for c,title,_ in cs)
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Сушка акварели — выбор вариантов</title><style>*{box-sizing:border-box}body{margin:0;background:#f0ede7;color:#242220;font:16px system-ui}main{max-width:1600px;margin:auto;padding:24px}h1{font-size:26px}p{line-height:1.5;max-width:1100px}button{font:inherit;border:1px solid #b6afa5;border-radius:7px;padding:8px 12px;background:#fff;color:inherit;cursor:pointer}button[aria-pressed=true]{background:#3e3862;color:white}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}section[hidden]{display:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}article{background:white;padding:12px;border-radius:9px;display:flex;flex-direction:column}h3{margin:0;font-size:17px}.sub{font-size:13px;color:#625e58;min-height:38px}.full{display:block;margin:auto 0}img{width:100%;height:auto;display:block}.timing{font-variant-numeric:tabular-nums}.copy{font-size:13px;align-self:start}details{margin-top:24px}#status{min-height:24px;font-size:14px}@media(max-width:650px){main{padding:12px}h1{font-size:22px}.grid{grid-template-columns:1fr}}</style><main><h1>Сушка акварели: что сохраняет красивый результат?</h1><p>Сравни варианты <b>0–4</b>. Ноль — принятая Г/v4. Остальные используют два новых способа переноса пигмента. Во всех сохранены общая вода, кисть и исходная подача Г. Мини-стенд пока остаётся на нуле.</p><div class="controls" id="device"><button data-device="samsung" aria-pressed="true">Samsung</button><button data-device="amd" aria-pressed="false">Ноутбук AMD</button></div><div class="controls" id="cases">'''+buttons+'''</div><p id="legend">Картинки и время полного расчёта с Samsung. Два числа — первый и повторный прогон пересечения. Нажми картинку для полного размера.</p><p id="status" role="status"></p>'''+''.join(sections)+'''<details><summary>Что измерено и что пока не доказано</summary><p>Время от первой принятой операции до завершения реплея, сушки и GPU. Загрузка бумаги, чтение суммы пигмента и экспорт PNG исключены. Это не задержка пера. Для пересечения есть два прогона Samsung, для остальных образцов — один: статистически надёжного бенчмарка пока нет, первый прогон может включать компиляцию шейдера.</p><p>Расчёт 1024×1024, тонкая бумага. Большой шаг смешивает краску несколькими выборками по потоку; консервативный вариант заменяет мелкие обмены дальними. Готовый RGB не переносится. Изменение суммы поля пигмента мало на этих образцах, но это не доказательство точного сохранения массы в любом рисунке. Подтверждение на 36 мазках и перенос в живую модель ещё впереди.</p><a href="results.json">Все измерения и SHA исходников</a></details></main><script>const stats='''+json.dumps(stats,ensure_ascii=False)+''';let device='samsung';function update(){document.querySelectorAll('img').forEach(i=>{i.src=i.dataset[device];i.parentElement.href=i.src});document.querySelectorAll('.timing').forEach(p=>{const r=stats[p.dataset.key];p.textContent=(r[device].computeMs/1000).toFixed(2)+(device==='samsung'&&r.samsungRepeat?' / '+(r.samsungRepeat.computeMs/1000).toFixed(2):'')+' с'});document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.device===device)));document.querySelector('#legend').textContent='Картинки и время полного расчёта: '+(device==='samsung'?'Samsung. Два числа — первый и повторный прогон пересечения.':'ноутбук AMD. Один прогон на вариант.')+' Нажми картинку для полного размера.'}document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;update()});document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{document.querySelectorAll('section').forEach(s=>s.hidden=s.id!==b.dataset.case);document.querySelectorAll('[data-case]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.name);document.querySelector('#status').textContent='Скопировано: '+b.dataset.name}catch{document.querySelector('#status').textContent=b.dataset.name}});</script></html>'''
(dest/'index.html').write_text(page)
print(json.dumps({'directory':str(dest),'images':len(assets),'variants':len(vs),'cases':len(cs)}))
